import java.util.Scanner;

public class Main {
    static int masofa(String manba) {
        if (manba.equals("connected")) {
            return 0;
        }
        if (manba.equals("static")) {
            return 1;
        }
        if (manba.equals("ospf")) {
            return 110;
        }
        return 120;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int raqam = 1;
        int engMasofa = Integer.MAX_VALUE;
        int engPrefiks = -1;
        for (int i = 1; i <= n; i++) {
            String manba = in.next();
            int prefiks = in.nextInt();
            int m = masofa(manba);
            if (m < engMasofa || (m == engMasofa && prefiks > engPrefiks)) {
                engMasofa = m;
                engPrefiks = prefiks;
                raqam = i;
            }
        }
        System.out.println(raqam);
    }
}

