#include <iostream>
#include <string>
using namespace std;

int masofa(const string& manba) {
    if (manba == "connected") {
        return 0;
    }
    if (manba == "static") {
        return 1;
    }
    if (manba == "ospf") {
        return 110;
    }
    return 120;
}

int main() {
    int n;
    cin >> n;
    int raqam = 1;
    int engMasofa = 1000000000;
    int engPrefiks = -1;
    for (int i = 1; i <= n; i++) {
        string manba;
        int prefiks;
        cin >> manba >> prefiks;
        int m = masofa(manba);
        if (m < engMasofa || (m == engMasofa && prefiks > engPrefiks)) {
            engMasofa = m;
            engPrefiks = prefiks;
            raqam = i;
        }
    }
    cout << raqam << endl;
    return 0;
}
